The previous result incorrectly treated the final platform as if only occupied pistons could fire. The rules say one of three pistons fires, so an empty piston can fire without ejecting the remaining ball. I’m correcting that boundary condition and recomputing all probabilities.
```python
context_marker = search_result
states = {((1, 2, 3), 4): 1.0}
win_corrected = [0.0] * 101
discard_corrected = [0.0] * 101

for step in range(2000):
    new_states = {}
    for (plat, nxt), mass in states.items():
        for pos in range(3):
            q = mass / 3.0
            target = plat[pos]
            if target is None:
                key = (plat, nxt)
            else:
                win_corrected[target] += q
                if pos == 0:
                    new_plat = (plat[1], plat[2], None)
                elif pos == 1:
                    if plat[0] is not None:
                        discard_corrected[plat[0]] += q
                    new_plat = (plat[2], None, None)
                else:
                    if plat[0] is not None:
                        discard_corrected[plat[0]] += q
                    new_plat = (plat[1], None, None)
                new_plat = list(new_plat)
                next_nxt = nxt
                while len([x for x in new_plat if x is not None]) < 3 and next_nxt <= 100:
                    for j in range(3):
                        if new_plat[j] is None:
                            new_plat[j] = next_nxt
                            next_nxt += 1
                            break
                key = (tuple(new_plat), next_nxt)
            new_states[key] = new_states.get(key, 0.0) + q
    states = {k: v for k, v in new_states.items() if v > 1e-16}
    if not states:
        break

ranking_corrected = sorted(
    ((win_corrected[i], i) for i in range(1, 101)),
    reverse=True
)
best_probability_corrected, best_ball_corrected = ranking_corrected[0]
print(f"best_ball={best_ball_corrected}; best_probability={best_probability_corrected:.12f}; top10={ranking_corrected[:10]}; residual_mass={sum(states.values()):.3e}; context_used={len(context_marker)}")
```

